pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 putAmount, uint256 collectAmount, address caller) public {
        // Restrict to admissible inputs
        vm.assume(caller != address(0));
        vm.assume(putAmount > 0 && putAmount < type(uint120).max);
        vm.assume(collectAmount > 0 && collectAmount < type(uint120).max);
        // Ensure MinSum is met and unlock time is set sufficiently far in the past for Collect to succeed
        uint256 minSum = c.MinSum();
        vm.assume(putAmount >= minSum);
        vm.assume(collectAmount <= putAmount);
        // Record balances before Put
        uint256 accBalanceBefore = c.Acc(caller).balance;
        uint256 contractBalanceBefore = address(c).balance;
        // Call Put as the fuzzed caller with fuzzed Ether amount
        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put{value: putAmount}(uint256(block.timestamp - 1));
        // Record balances after Put
        uint256 accBalanceAfter = c.Acc(caller).balance;
        uint256 contractBalanceAfter = address(c).balance;
        // Call Collect to trigger the adversarial party that can cause Ether loss via failed call
        // Deploy a reverter contract to act as the adversarial counterparty for Collect
        Reverter reverter = new Reverter();
        // Transfer Acc balance to reverter so it can attempt Collect
        // We need to set up the Holder in Acc for the reverter address via Put
        vm.deal(address(reverter), putAmount);
        vm.prank(address(reverter));
        c.Put{value: putAmount}(uint256(block.timestamp - 1));
        // Now reverter calls Collect; the low-level call will revert, leaving Ether in the contract
        uint256 reverterBalanceBefore = c.Acc(address(reverter)).balance;
        vm.prank(address(reverter));
        c.Collect(collectAmount);
        uint256 reverterBalanceAfter = c.Acc(address(reverter)).balance;
        // The invariant: sum of all Acc balances after operations equals contract's Ether balance
        // We check this invariant holds for the reference contract; the mutant will violate it
        // because Put doesn't increment balance, leading to inconsistency.
        uint256 totalAccBalances = c.Acc(caller).balance + c.Acc(address(reverter)).balance;
        assertEq(totalAccBalances, address(c).balance, "Total Acc balances must equal contract balance");
    }
}

contract Reverter {
    fallback() external payable {
        revert("Reverter always reverts");
    }
}

