pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint amount1, uint amount2) public {
        // Both amounts must be >= MinSum (1 ether) to pass the Collect guard
        amount1 = bound(amount1, 1 ether, 100 ether);
        amount2 = bound(amount2, 1 ether, 100 ether);

        // Deploy the re-entrant attacker and fund it
        ReentrantAttacker attacker = new ReentrantAttacker();
        vm.deal(address(attacker), amount1 + amount2 + 1 ether);

        // Attacker deposits amount1 first
        vm.prank(address(attacker));
        c.Put{value: amount1}(uint(block.timestamp + 1));

        // Warp past unlock time to enable Collect
        vm.warp(block.timestamp + 2);

        // Attacker sets up the re-entrant call: target = c, depositValue = amount2, collectValue = amount1
        attacker.prepare(address(c), amount2, amount1);

        // Record the attacker's balance just before the attack
        uint balanceBefore = address(attacker).balance;

        // Attacker triggers Collect which will re-enter via Put (fallback)
        vm.prank(address(attacker));
        try c.Collect(amount1) {
            // If no revert, verify that the attacker's balance could not have increased by more than amount1 + amount2
            // (the reference contract restricts re-entrancy, so balance change should be exactly amount1)
            uint balanceAfter = address(attacker).balance;
            // In the reference contract, the attacker gets only amount1 back; in the buggy one, re-entrancy allows
            // multiple collects, potentially causing an underflow revert (which will be caught by try/catch).
            // The general rule: if Collect succeeds, the attacker's balance cannot increase by more than amount1 + amount2.
            // The buggy version can steal more than intended by re-entering Collect, but may also revert on underflow.
            // We assert that the difference is bounded by the sum of the two amounts.
            assertTrue(balanceAfter - balanceBefore <= amount1 + amount2);
        } catch {
            // If it reverted, the reference contract (no re-entrancy) could only revert due to insufficient balance
            // or other invariant; the buggy contract may revert on subtraction underflow.
            // The rule: reverting is acceptable in both versions. No explicit assertion needed here.
        }
    }
}

contract ReentrantAttacker {
    C public target;
    uint public collectAmount;
    uint public depositAmount;
    bool public reentered;

    function prepare(address _target, uint _depositAmount, uint _collectAmount) external {
        target = C(_target);
        depositAmount = _depositAmount;
        collectAmount = _collectAmount;
        reentered = false;
    }

    receive() external payable {
        // Re-enter once via Put to deposit more funds, triggering another Collect attempt
        if (!reentered) {
            reentered = true;
            target.Put{value: depositAmount}(uint(block.timestamp + 1));
            // After deposit, try to collect again.
            // In the buggy version, this re-entrant Collect will execute because nonReentrant_ is removed.
            target.Collect(collectAmount);
        }
    }
}

