        // Record attacker's balance before the put.
        uint256 preBalance = c.Acc(address(attacker)).balance;

        // Attacker performs a Put, which triggers re-entrant Collect in the fallback/receive of the helper.
        attacker.attack(depositAmount, collectAmount, unlockTime);

        uint256 postBalance = c.Acc(address(attacker)).balance;

        // Property: Post-balance must be >= pre-balance (no drain through re-entrancy).
