pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 seed) public {
        // Restrict amount to admissible domain: at least MinSum, not too large
        vm.assume(amount >= 1 ether && amount <= 1000 ether);
        vm.assume(unlockTime <= type(uint64).max);
        // Generate a distinct caller from seed
        address caller = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(caller != address(this) && caller != address(0));

        // Set up caller with balance and unlockTime that passes the Collect condition
        vm.deal(caller, amount * 2);
        vm.startPrank(caller);
        c.Put{value: amount}(unlockTime);
        vm.stopPrank();

        // Fast-forward past unlockTime
        vm.warp(block.timestamp + unlockTime + 1);

        // Record balance before Collect
        (uint256 beforeUnlock, uint256 beforeBal) = c.Acc(caller);

        // Call Collect as caller
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", amount));

        // Read balance after
        (uint256 afterUnlock, uint256 afterBal) = c.Acc(caller);

        // General rule: if Collect did not revert AND the conditions were satisfied,
        // the caller's balance should be reduced by exactly the amount.
        // Conditions: beforeBal >= 1 ether, beforeBal >= amount, block.timestamp > beforeUnlock
        if (ok && beforeBal >= 1 ether && beforeBal >= amount && block.timestamp > beforeUnlock) {
            assertEq(afterBal, beforeBal - amount, "balance deduction invariant violated");
        } else {
            // If it reverted or conditions were not met, balance must be unchanged
            assertEq(afterBal, beforeBal, "balance changed unexpectedly");
        }
    }
}

