        // The reference deducts balance; bug does not.
        bool collectionSucceeded = balanceAfter > balanceBefore;
        uint256 accBalance = c.Acc(address(this)).balance;

        if (collectionSucceeded) {
            assertEq(accBalance, _depositAmt - _collectAmt);
        }

        // Universal property: after a successful Collect, Acc balance must equal initial deposit minus collected amount.
        // The bug leaves Acc balance unchanged, violating this equality.
    }
